"""What the model is allowed to see: names, descriptions and schemas (plan T3.1).

Three independent readings of the same contract, which is the whole point — they fail in
different ways and none of them can cover for another:

* **`from_registry`** imports `server.create_server` and asks the server object itself. No
  Docker, no network, ~50 ms. This is the reading a pull request can afford on every push.
* **`from_wire`** reads a live `tools/list` off the shipped container. It is the only reading
  that can catch an image whose `COPY` list forgot a module, or a `:latest` that is not the
  tree it claims to be — the failure that has shipped twice.
* **`docstrings_from_source`** parses `server.py` with `ast` and never imports it. It answers
  "is the text the model reads the text that is written in this repository", without trusting
  the decorator that produced it. `inspect.getdoc()` on the registered function cannot answer
  that: it reads `__doc__` off the object the framework handed back, so the comparison would be
  the framework agreeing with itself.

All three readings are compared **dedented** — see `_entry` for the measurement that forced
that and for what it costs.

The committed snapshot (`fixtures/expected_tools.json`) pins every description's text and both
schemas byte for byte. That is deliberate churn: "docstrings are the contract" is a stated
convention of this repository, and a contract that can change without appearing in a diff is not
one. Regenerate it on purpose, never to make a red test green:

    .venv/bin/python -m harness.tool_contract        # from tests/e2e/
"""

from __future__ import annotations

import ast
import asyncio
import inspect
import json
import sys
from collections.abc import Callable
from pathlib import Path
from typing import Any
from unittest.mock import MagicMock

__all__ = [
    "CONTRACT_PATH",
    "DESTRUCTIVE_PREFIX",
    "MAX_PAGES",
    "SERVER_PATH",
    "build",
    "docstrings_from_source",
    "from_registry",
    "from_wire",
    "load",
    "read_pages",
    "write",
]

REPO_ROOT = Path(__file__).resolve().parents[3]
SERVER_PATH = REPO_ROOT / "server.py"
CONTRACT_PATH = Path(__file__).resolve().parents[1] / "fixtures" / "expected_tools.json"

DESTRUCTIVE_PREFIX = "gramps_delete_"
REGISTER_DECORATOR = "register"
MAX_PAGES = 20


def _entry(description: str | None, input_schema: Any, output_schema: Any) -> dict[str, Any]:
    """One tool, reduced to the three fields a client actually reasons about.

    `title`, `annotations`, `icons` and `meta` are dropped on purpose: they are `None` for
    every tool this server registers, so pinning them would pin the absence of a feature and
    turn a harmless library upgrade into a red suite.

    **The description is dedented, and that is not cosmetic.** Python 3.13 began dedenting
    docstrings at compile time; the shipped image is `python:3.12-slim` and does not. Measured
    on 2026-08-01: the same tool arrives over the wire as
    `"...guard.\\n\\n        items: [...]"` from the container and as
    `"...guard.\\n\\nitems: [...]"` from a 3.14 host. Pinning the raw bytes would therefore
    make this suite red whenever the developer's interpreter differs from the image's — the
    harness accusing the product, which is the one failure this suite may not produce. What is
    pinned is the text; what is deliberately not pinned is its leading whitespace.
    """
    return {
        "description": None if description is None else inspect.cleandoc(description),
        "inputSchema": input_schema,
        "outputSchema": output_schema,
    }


def from_registry(*, enable_destructive: bool) -> dict[str, dict[str, Any]]:
    """Ask the server object, in this process, with a mock client behind it."""
    if str(REPO_ROOT) not in sys.path:
        # pytest puts the repo root on the path for the test run; the regeneration entry
        # point is invoked from tests/e2e and would not find `server` without this.
        sys.path.insert(0, str(REPO_ROOT))
    import server

    mcp, _tools = server.create_server(MagicMock(), enable_destructive=enable_destructive)
    listed = asyncio.run(mcp.list_tools())
    return {
        tool.name: _entry(tool.description, tool.inputSchema, tool.outputSchema) for tool in listed
    }


def from_wire(pages: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    """Read the same contract off `tools/list` replies — every page, not the first.

    `outputSchema` is absent rather than null on the wire when a tool has none, so it is read
    with `.get`; `description` is not, because a tool without one is a finding, not a default.
    """
    return {
        tool["name"]: _entry(
            tool.get("description"), tool.get("inputSchema"), tool.get("outputSchema")
        )
        for page in pages
        for tool in page.get("tools", [])
    }


def read_pages(
    list_tools: Callable[[str | None], dict[str, Any]], *, max_pages: int = MAX_PAGES
) -> list[dict[str, Any]]:
    """Every `tools/list` page, followed by its `nextCursor`.

    A single page is not the tool set, and only `nextCursor` says so. The page limit is not
    defensive decoration: a server that echoes the same cursor back would hang the suite
    instead of failing it, and a hang has no failing assertion to read.
    """
    collected: list[dict[str, Any]] = []
    cursor: str | None = None
    while True:
        page = list_tools(cursor)
        collected.append(page)
        cursor = page.get("nextCursor")
        if not cursor:
            return collected
        if len(collected) >= max_pages:
            raise RuntimeError(
                f"tools/list still offered a cursor after {max_pages} pages — "
                "the server is paginating without end"
            )


def docstrings_from_source(path: Path = SERVER_PATH) -> dict[str, str | None]:
    """Every `@register`-decorated function in `create_server`, mapped to its docstring.

    Parsed, not imported: the question is what the repository says, and an import would answer
    with what the framework made of it.
    """
    tree = ast.parse(path.read_text(encoding="utf-8"))
    factory = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name == "create_server"
    )
    return {
        node.name: ast.get_docstring(node, clean=True)
        for node in ast.walk(factory)
        if isinstance(node, ast.FunctionDef) and _is_registered(node)
    }


def _is_registered(node: ast.FunctionDef) -> bool:
    return any(
        isinstance(decorator, ast.Name) and decorator.id == REGISTER_DECORATOR
        for decorator in node.decorator_list
    )


def build() -> dict[str, Any]:
    """The snapshot as it is committed: the armed tool set, plus the unarmed name list.

    Both gates come from the same import, so the snapshot cannot record a 31 that was measured
    while the 27 was assumed.
    """
    armed = from_registry(enable_destructive=True)
    unarmed = from_registry(enable_destructive=False)
    return {
        "regenerate_with": "cd tests/e2e && python -m harness.tool_contract",
        "gate_off": sorted(unarmed),
        "tools": {name: armed[name] for name in sorted(armed)},
    }


def load(path: Path = CONTRACT_PATH) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def write(path: Path = CONTRACT_PATH) -> dict[str, Any]:
    snapshot = build()
    path.write_text(json.dumps(snapshot, indent=2, sort_keys=False) + "\n", encoding="utf-8")
    return snapshot


